-- The two checklists published on 2026-10-11: someone else's good news
-- landing badly (Comparison) and the early dark (Seasons).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-11`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('when-someone-elses-good-news-stings', 'When Someone Else''s Good News Stings', 'For the moment a friend''s promotion, engagement or baby announcement lands with a thud instead of joy. It helps you let the feeling pass without acting on it, answer them like someone who cares, and look at what the sting is pointing at.', 'Comparison', '["Say the ugly reaction to yourself once — unspoken envy runs the show for longer.", "Send the congratulations anyway, briefly — the feeling is yours, the message is theirs.", "Wait a day before you post anything — comparison writes bad replies.", "Close the app for the rest of the evening — the feed will keep handing you more of this.", "Name what you actually want underneath it — envy points at something, usually accurately.", "Write one step toward that thing this month — wanting it is more useful aimed somewhere.", "List two things going well for you now — not to score it, just to widen the frame.", "Tell one honest person how it landed — saying it out loud takes most of the charge out."]'::jsonb, 'as needed', array['Self-Esteem', 'Shame']::text[], 1, '2026-10-11T16:00:00+00:00'::timestamptz),
  ('when-the-dark-comes-earlier', 'When the Dark Comes Earlier', 'For the weeks when it is dark before you finish work and the evenings stretch out. It helps you get light early, keep something in the calendar each week, and notice the slide before it has taken the whole season.', 'Seasons', '["Get outside within an hour of waking — morning light does more than a lamp at night.", "Eat lunch by a window or outdoors — the middle of the day is the brightest light you get.", "Put one thing in the calendar for each week — dark evenings empty out if nothing is booked.", "Turn on lamps before it gets dark, not after — the room matters more once the window is black.", "Keep the walk you had in summer, shorter — a habit survives better than it restarts.", "Hold your wake-up time steady on weekends — the clock drifts fastest in the dark months.", "Write down how you felt in January last year — a pattern you can see is easier to plan around.", "Tell your doctor if this happens every year — a seasonal pattern is worth a conversation."]'::jsonb, 'weekly', array['Self-Care', 'Movement']::text[], 1, '2026-10-11T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
